import pygame

def step(x, y, vx, vy, dt, left_y, right_y):
    x += vx * dt
    y += vy * dt
    if y <= 6 and vy < 0:
        y, vy = 6, -vy
    elif y >= 394 and vy > 0:
        y, vy = 394, -vy
    ball = pygame.Rect(x - 6, y - 6, 12, 12)
    left = pygame.Rect(20, left_y, 10, 60)
    right = pygame.Rect(610, right_y, 10, 60)
    if ball.colliderect(left) and vx < 0:
        x, vx = 36, -vx
    elif ball.colliderect(right) and vx > 0:
        x, vx = 604, -vx
    if x < -6 or x > 646:
        x, y, vx, vy = 320.0, 200.0, 200.0, 100.0
    return x, y, vx, vy
